// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.security.supplychain/** * NOUS — Threat severity (Module 12, Defense Layer 1). * * Strategy §12.7 — each detected threat carries a severity used by * [SupplyChainMonitor] to compute the overall [ThreatState]. * *   - **LOW** — informational only (e.g., app is debuggable by design). *     Operation continues normally; logged for telemetry. *   - **MEDIUM** — suspicious (e.g., Xposed installed but not active). *     Operation continues with elevated audit logging. *   - **HIGH** — likely compromised (e.g., Magisk root binary present). *     Sensitive operations require additional authentication. *   - **CRITICAL** — definitively compromised (e.g., Frida server actively *     hooking the app). Sensitive features disabled. * * Severity ordering: `CRITICAL > HIGH > MEDIUM > LOW`. */enum class ThreatSeverity {    LOW,    MEDIUM,    HIGH,    CRITICAL;    /** True if this severity is at least as severe as [other]. */    fun isAtLeast(other: ThreatSeverity): Boolean = this.ordinal >= other.ordinal}/** * NOUS — A single detected threat. * * @param name short machine-readable name (e.g., "magisk_root", *   "frida_server", "debugger_attached", "emulator_detected"). * @param severity how serious this threat is. * @param detail optional human-readable detail for logging. */data class Threat(    val name: String,    val severity: ThreatSeverity,    val detail: String? = null,)/** * NOUS — Overall threat state (Module 12, Defense Layer 1). * * Strategy §12.7 — aggregate state computed from the list of [Threat]s: * *   - **CLEAN** — zero threats detected. App is running in a normal *     production environment. *   - **SUSPICIOUS** — only LOW/MEDIUM threats. Operation continues with *     elevated audit logging; user is NOT shown a warning. *   - **COMPROMISED** — at least one HIGH or CRITICAL threat. NOUS disables *     sensitive features (credential vault, banking app guard, backup/restore) *     and shows a warning: "Security threat detected. Sensitive features *     have been disabled." * * State transitions: CLEAN → SUSPICIOUS → COMPROMISED (escalation) and * reverse (de-escalation). The state never goes from COMPROMISED straight * to CLEAN — must pass through SUSPICIOUS (one scan with no HIGH/CRITICAL * threats first). * * @see SupplyChainMonitor.scan */enum class ThreatState {    CLEAN,    SUSPICIOUS,    COMPROMISED;    companion object {        /**         * Compute the overall [ThreatState] from a list of detected threats.         *         * - Empty list → CLEAN         * - Any CRITICAL or HIGH → COMPROMISED         * - Only LOW or MEDIUM → SUSPICIOUS         */        fun fromThreats(threats: List<Threat>): ThreatState = when {            threats.any {                it.severity == ThreatSeverity.CRITICAL ||                    it.severity == ThreatSeverity.HIGH            } -> COMPROMISED            threats.isEmpty() -> CLEAN            else -> SUSPICIOUS        }    }}/** * NOUS — Scan result returned by [SupplyChainMonitor.scan]. * * @param state overall [ThreatState]. * @param threats list of individual threats detected (empty if CLEAN). * @param scannedAt epoch millis when the scan was performed. * @param durationMs wall-clock duration of the scan. */data class ScanResult(    val state: ThreatState,    val threats: List<Threat>,    val scannedAt: Long = System.currentTimeMillis(),    val durationMs: Long,) {    /** True if [state] is [ThreatState.COMPROMISED]. */    val isCompromised: Boolean get() = state == ThreatState.COMPROMISED    /** True if [state] is not [ThreatState.CLEAN]. */    val hasThreats: Boolean get() = threats.isNotEmpty()}